import ast, re
src = open("grokking_optimizers/compile.py").read()
tree = ast.parse(src)
for node in ast.walk(tree):
    if isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name) and t.id == "STALL_DIM_HINTS":
                val = node.value
                if isinstance(val, ast.Dict):
                    print("STALL_DIM_HINTS top-level keys:", len(val.keys))
                    print("keys:", [k.value if isinstance(k, ast.Constant) else "?" for k in val.keys])
    if isinstance(node, ast.AnnAssign):
        if isinstance(node.target, ast.Name) and node.target.id == "STALL_DIM_HINTS":
            val = node.value
            if isinstance(val, ast.Dict):
                print("STALL_DIM_HINTS (annotated) top-level keys:", len(val.keys))
                print("keys:", [k.value if isinstance(k, ast.Constant) else "?" for k in val.keys])
